script:
// FPS Overview strip -- design 1a, step 6.
//
// One frappe.call to one whitelisted read-only method. The method omits any tile
// whose doctype the caller cannot read, so this renders what the viewer is
// entitled to see and never reveals the existence of the rest.
//
// LIVE REFRESH. Polls every 30s so counts move without a manual page reload.
// The interval checks the block's own DOM node is still attached before each
// tick and clears itself the moment it is not -- the block's container gets
// replaced wholesale on every workspace navigation, with no teardown hook of
// its own to unhook from, so this is what stops a poll loop for a page the
// viewer has since left from running forever in the background.

(function () {
	var scope =
		typeof root_element !== "undefined" && root_element ? root_element : document;

	var grid = scope.querySelector('[data-fps="grid"]');
	var foot = scope.querySelector('[data-fps="foot"]');
	var meta = scope.querySelector('[data-fps="meta"]');
	if (!grid) return;

	var REFRESH_MS = 30000;

	// Tile identity colours, in workflow order. The handoff's oklch() values are
	// the intent, used verbatim here because inside a Custom HTML Block we own the
	// CSS -- unlike shortcuts and cards, which are limited to Frappe's palette.
	var COLOURS = {
		enquiry: "oklch(0.68 0.1 220)",
		quotation: "oklch(0.66 0.11 205)",
		job_order: "oklch(0.62 0.12 195)",
		customs: "oklch(0.65 0.14 75)",
		in_progress: "oklch(0.64 0.13 55)",
		delivered: "oklch(0.62 0.12 150)",
		invoices: "oklch(0.55 0.12 300)",
	};

	function esc(v) {
		return String(v == null ? "" : v).replace(/[&<>"']/g, function (c) {
			return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
		});
	}

	function render(data) {
		var tiles = (data && data.tiles) || [];
		if (!tiles.length) {
			grid.innerHTML = '<div class="fps-ov-msg">No stages are visible to you.</div>';
			return;
		}

		grid.innerHTML = tiles
			.map(function (t) {
				var colour = COLOURS[t.key] || "#94a3b8";
				var tag = t.route ? "a" : "div";
				var href = t.route ? ' href="' + esc(t.route) + '"' : "";
				return (
					"<" + tag + ' class="fps-ov-cell"' + href +
					' style="--fps-tile-color: ' + colour + '">' +
					'<span class="fps-ov-label">' + esc(t.label) + "</span>" +
					'<span class="fps-ov-count">' + esc(t.count) + "</span>" +
					'<span class="fps-ov-note">' + esc(t.note || "") + "</span>" +
					"</" + tag + ">"
				);
			})
			.join("");

		if (meta) meta.textContent = tiles.length + " stages";

		if (foot) {
			foot.innerHTML = ((data && data.footnotes) || [])
				.map(function (n) {
					return "<span>" + esc(n) + "</span>";
				})
				.join("");
		}
	}

	var loaded = false;
	function load() {
		frappe
			.call({ method: "fps_erpnext.api.pipeline.get_overview" })
			.then(function (r) {
				loaded = true;
				render(r && r.message);
			})
			.catch(function () {
				// Only the FIRST load's failure replaces the grid with an error --
				// a transient blip on a later poll should not blank out tiles that
				// were showing real counts a moment ago.
				if (!loaded) {
					grid.innerHTML = '<div class="fps-ov-msg">Could not load the overview.</div>';
				}
			});
	}

	load();
	var timer = setInterval(function () {
		if (!document.body.contains(grid)) {
			clearInterval(timer);
			return;
		}
		load();
	}, REFRESH_MS);
})();

style:
/* FPS Overview strip -- eight tiles that WRAP.
   The earlier version used grid-auto-flow: column, which forced one row and made
   the last tile scroll off the right. auto-fit + minmax reflows to 4x2 at desk
   width and 2x4 on a tablet, so nothing is ever hidden off-screen. */

.fps-ov {
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 10px;
	background: var(--card-bg, #fff);
	overflow: hidden;
}

.fps-ov-head {
	display: flex;
	align-items: baseline;
	gap: 10px;
	padding: 14px 16px 12px;
	flex-wrap: wrap;
}

.fps-ov-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text-color, #1f272e);
}

.fps-ov-help {
	font-size: 12px;
	color: var(--text-muted, #7c7c7c);
}

.fps-ov-meta {
	margin-left: auto;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	font-variant-numeric: tabular-nums;
}

.fps-ov-grid {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
	border-top: 1px solid var(--border-color, #e2e8f0);
}

.fps-ov-cell {
	position: relative;
	padding: 12px 14px 13px;
	border-left: 1px solid var(--border-color, #e2e8f0);
	border-top: 1px solid var(--border-color, #e2e8f0);
	margin-top: -1px;
	text-decoration: none;
	display: block;
	color: inherit;
	min-width: 0;
}

.fps-ov-cell:hover {
	background: var(--bg-light-gray, #f7f9fa);
	text-decoration: none;
}

/* 3px coloured top edge is the tile's identity. Sits above the wrap border. */
.fps-ov-cell::before {
	content: "";
	position: absolute;
	inset: 0 0 auto 0;
	height: 3px;
	background: var(--fps-tile-color, #94a3b8);
	z-index: 1;
}

.fps-ov-label {
	display: block;
	font-size: 11.5px;
	font-weight: 500;
	color: var(--text-muted, #7c7c7c);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.fps-ov-count {
	display: block;
	margin-top: 4px;
	font-size: 24px;
	font-weight: 600;
	line-height: 1.1;
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-variant-numeric: tabular-nums;
	color: var(--text-color, #1f272e);
}

.fps-ov-note {
	display: block;
	margin-top: 2px;
	font-size: 11px;
	color: var(--text-muted, #7c7c7c);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.fps-ov-foot {
	display: flex;
	flex-wrap: wrap;
	gap: 4px 14px;
	padding: 10px 16px 12px;
	border-top: 1px solid var(--border-color, #e2e8f0);
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
}

.fps-ov-foot span {
	font-variant-numeric: tabular-nums;
}

.fps-ov-msg {
	padding: 18px 16px;
	font-size: 12.5px;
	color: var(--text-muted, #7c7c7c);
}

script:
// Job Tracker board -- one row per open job, colour-coded by customer.
//
// Colour is assigned from the SORTED customer list the server returns, so a
// given customer keeps the same colour across reloads. Deriving it from row
// order instead would reshuffle every time a job was touched.
//
// LIVE REFRESH. Polls every 30s -- see fps_overview.js for why the interval
// checks the block's own node is still attached before each tick rather than
// relying on any teardown hook, which these blocks do not get.

(function () {
	var scope =
		typeof root_element !== "undefined" && root_element ? root_element : document;

	var body = scope.querySelector('[data-fps="rows"]');
	var legend = scope.querySelector('[data-fps="legend"]');
	var meta = scope.querySelector('[data-fps="meta"]');
	if (!body) return;

	var REFRESH_MS = 30000;

	// Customer palette. Deliberately distinct from the five status hues, which
	// carry fixed meanings -- customer identity and job status must not be
	// confusable for one another.
	var PALETTE = [
		"#0B4FE0", "#22D3EE", "#8F4CFF", "#0EA5E9", "#14B8A6",
		"#F59E0B", "#EC4899", "#64748B", "#7C3AED", "#0891B2",
		"#A16207", "#BE185D",
	];

	var STAGE = {
		New: ["#eff6ff", "#1d4ed8"],
		"Docs received": ["#fff7ed", "#b45309"],
		"In Progress": ["#fef3c7", "#92400e"],
		"Cleared - Ready": ["#ede9fe", "#6d28d9"],
		Delivered: ["#dcfce7", "#15803d"],
		Invoiced: ["#f3e8ff", "#7e22ce"],
		"On Hold": ["#fee2e2", "#b91c1c"],
		Closed: ["#f1f5f9", "#475569"],
	};

	function esc(v) {
		return String(v == null ? "" : v).replace(/[&<>"']/g, function (c) {
			return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
		});
	}

	function render(data) {
		var jobs = (data && data.jobs) || [];
		var customers = (data && data.customers) || [];

		if (!jobs.length) {
			body.innerHTML =
				'<tr><td colspan="8" class="fps-jt-msg">No open jobs.</td></tr>';
			return;
		}

		var colourOf = {};
		customers.forEach(function (c, i) {
			colourOf[c] = PALETTE[i % PALETTE.length];
		});

		if (legend) {
			legend.innerHTML = customers
				.map(function (c) {
					return (
						'<span class="fps-jt-chip" style="--fps-cust-color: ' +
						colourOf[c] + '"><i></i><span>' + esc(c) + "</span></span>"
					);
				})
				.join("");
		}

		body.innerHTML = jobs
			.map(function (j) {
				var pill = STAGE[j.stage] || ["#f1f5f9", "#475569"];
				return (
					'<tr data-job="' + esc(j.name) + '" title="' + esc(j.name) + '">' +
					'<td class="fps-jt-status"><span class="fps-jt-pill" style="--fps-stage-bg: ' +
					pill[0] + "; --fps-stage-fg: " + pill[1] + '">' +
					esc(j.stage || "—") + "</span></td>" +
					'<td class="fps-jt-cust" style="--fps-cust-color: ' +
					(colourOf[j.customer] || "transparent") + '">' +
					esc(j.customer || "—") + "</td>" +
					'<td class="fps-jt-jo">' + esc(j.name) + "</td>" +
					'<td class="fps-jt-ref">' + esc(j.reference || "—") + "</td>" +
					'<td class="fps-jt-sow" title="' + esc(j.sow) + '">' +
					esc(j.sow || "—") + "</td>" +
					'<td class="fps-jt-cons" title="' + esc(j.consignment) + '">' +
					esc(j.consignment || "—") + "</td>" +
					'<td class="fps-jt-route" title="' + esc(j.route) + '">' +
					esc(j.route || "—") + "</td>" +
					'<td class="fps-jt-eta">' + esc(j.eta || "—") + "</td>" +
					"</tr>"
				);
			})
			.join("");

		if (meta) {
			meta.textContent =
				jobs.length + " open jobs · " + customers.length + " customers";
		}
	}

	// Row click opens the job order itself -- its update log (what this board's
	// status column and every row here is built from) is a grid directly on
	// that form now, not a separate document to look up first. Delegated so it
	// survives every re-render, and routed through frappe.set_route rather than
	// an <a href> so the desk navigates in place instead of doing a full page
	// reload.
	body.addEventListener("click", function (e) {
		var row = e.target.closest("tr[data-job]");
		if (!row) return;
		frappe.set_route("Form", "Job Order", row.getAttribute("data-job"));
	});

	var loaded = false;
	function load() {
		frappe
			.call({ method: "fps_erpnext.api.pipeline.get_job_tracker" })
			.then(function (r) {
				loaded = true;
				render(r && r.message);
			})
			.catch(function () {
				// Only the first load's failure replaces the board with an error --
				// a later poll that briefly fails should leave the last good rows
				// on screen rather than blank them.
				if (!loaded) {
					body.innerHTML =
						'<tr><td colspan="8" class="fps-jt-msg">Could not load the job tracker.</td></tr>';
				}
			});
	}

	load();
	var timer = setInterval(function () {
		if (!document.body.contains(body)) {
			clearInterval(timer);
			return;
		}
		load();
	}, REFRESH_MS);
})();

style:
/* Job Tracker board -- one row per open job, colour-coded by customer.
   The five status colours keep their fixed meanings from the handoff and are
   NOT reused for customers; customer identity is carried by the left rail and
   the legend chip, status by the pill. Two separate encodings, so neither can
   be mistaken for the other. */

.fps-jt {
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 10px;
	background: var(--card-bg, #fff);
	overflow: hidden;
}

.fps-jt-head {
	display: flex;
	align-items: baseline;
	gap: 10px;
	padding: 14px 16px 12px;
	flex-wrap: wrap;
}

.fps-jt-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text-color, #1f272e);
}

.fps-jt-help {
	font-size: 12px;
	color: var(--text-muted, #7c7c7c);
}

.fps-jt-meta {
	margin-left: auto;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	font-variant-numeric: tabular-nums;
}

.fps-jt-legend {
	display: flex;
	flex-wrap: wrap;
	gap: 6px 14px;
	padding: 0 16px 12px;
}

.fps-jt-chip {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	max-width: 240px;
}

.fps-jt-chip i {
	width: 9px;
	height: 9px;
	border-radius: 3px;
	background: var(--fps-cust-color, #94a3b8);
	flex: none;
}

.fps-jt-chip span {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.fps-jt-scroll {
	overflow-x: auto;
	border-top: 1px solid var(--border-color, #e2e8f0);
}

/* table-layout: fixed makes the <colgroup> widths authoritative. Without it the
   browser sizes columns from content, which is what left a gulf between
   "Customer ref" and "Scope of work" -- one long SOW string was pushing the
   remaining columns off to the right. */
.fps-jt-table {
	width: 100%;
	/* Below this the percentage columns would crush the three fixed-length ones
	   back into ellipsis. The container scrolls instead. */
	min-width: 1120px;
	table-layout: fixed;
	border-collapse: collapse;
	font-size: 12.5px;
}

.fps-jt-table th {
	text-align: left;
	font-size: 10.5px;
	font-weight: 600;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-muted, #7c7c7c);
	padding: 9px 10px;
	border-bottom: 1px solid var(--border-color, #e2e8f0);
	white-space: nowrap;
}

.fps-jt-table td {
	padding: 8px 10px;
	border-bottom: 1px solid var(--border-color, #f1f5f9);
	vertical-align: middle;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.fps-jt-table tr:last-child td {
	border-bottom: 0;
}

/* Whole row is the click target, so it must look like one. */
.fps-jt-table tbody tr {
	cursor: pointer;
}

.fps-jt-table tbody tr:hover {
	background: var(--bg-light-gray, #f7f9fa);
}

.fps-jt-status {
	white-space: nowrap;
}

/* Customer identity: coloured left rail plus the name. */
td.fps-jt-cust {
	border-left: 3px solid var(--fps-cust-color, transparent);
	font-weight: 500;
	color: var(--text-color, #1f272e);
}

.fps-jt-jo {
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-size: 11.5px;
	color: var(--text-color, #1f272e);
}

.fps-jt-ref,
.fps-jt-eta {
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
}

.fps-jt-sow,
.fps-jt-cons,
.fps-jt-route {
	color: var(--text-muted, #55606b);
}

.fps-jt-pill {
	display: inline-block;
	padding: 2px 8px;
	border-radius: 20px;
	font-size: 11px;
	font-weight: 600;
	white-space: nowrap;
	background: var(--fps-stage-bg, #f1f5f9);
	color: var(--fps-stage-fg, #475569);
}

.fps-jt-msg {
	padding: 18px 16px;
	font-size: 12.5px;
	color: var(--text-muted, #7c7c7c);
	text-align: left;
	white-space: normal;
}

script:
// Customs board -- a spreadsheet filter view over every customs entry.
//
// Each filterable column carries its own dropdown. The dropdowns CASCADE, the
// way an autofilter does: the options offered for a column are the values still
// reachable given every OTHER column's filter. Offering the full value list
// instead would let you pick a combination that returns nothing, which is the
// usual way these grids waste your time.
//
// A column's own selection is never removed from its own list, so you can always
// undo a choice that has narrowed everything else to nothing.
//
// LIVE REFRESH. Polls every 30s for new/changed rows -- see fps_overview.js
// for why the interval checks the block's own node is still attached before
// each tick. Only the ROWS are re-fetched and re-rendered; the header (and
// its filter dropdowns' change listener) is built exactly once, and whatever
// the viewer has chosen in `chosen` / typed into `term` carries across every
// poll untouched -- a background refresh must never reset someone's filters
// out from under them mid-review.

(function () {
	var scope =
		typeof root_element !== "undefined" && root_element ? root_element : document;

	var labelRow = scope.querySelector('[data-fps="labels"]');
	var filterRow = scope.querySelector('[data-fps="filters"]');
	var body = scope.querySelector('[data-fps="rows"]');
	var meta = scope.querySelector('[data-fps="meta"]');
	var search = scope.querySelector('[data-fps="search"]');
	var clear = scope.querySelector('[data-fps="clear"]');
	if (!body) return;

	var REFRESH_MS = 30000;

	var STATUS = {
		Pending: ["#fff7ed", "#b45309"],
		"In Process": ["#fef3c7", "#92400e"],
		Cleared: ["#dcfce7", "#15803d"],
		"On Hold": ["#fee2e2", "#b91c1c"],
		Delayed: ["#fee2e2", "#b91c1c"],
	};

	var columns = [];
	var rows = [];
	var chosen = {}; // column key -> selected value ("" means no filter)
	var term = "";

	function esc(v) {
		return String(v == null ? "" : v).replace(/[&<>"']/g, function (c) {
			return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
		});
	}

	function matches(row, skipKey) {
		for (var key in chosen) {
			if (key === skipKey || !chosen[key]) continue;
			if (row[key] !== chosen[key]) return false;
		}
		if (term) {
			var hay = columns
				.map(function (c) {
					return row[c.key];
				})
				.join(" ")
				.toLowerCase();
			if (hay.indexOf(term) === -1) return false;
		}
		return true;
	}

	function visible() {
		return rows.filter(function (r) {
			return matches(r, null);
		});
	}

	function buildHeader() {
		labelRow.innerHTML = columns
			.map(function (c) {
				return "<th>" + esc(c.label) + "</th>";
			})
			.join("");

		filterRow.innerHTML = columns
			.map(function (c) {
				if (!c.filterable) return "<th></th>";
				return (
					'<th><select class="fps-ct-select" data-col="' +
					esc(c.key) +
					'" aria-label="Filter by ' + esc(c.label) + '"></select></th>'
				);
			})
			.join("");

		filterRow.addEventListener("change", function (e) {
			var sel = e.target.closest("select[data-col]");
			if (!sel) return;
			chosen[sel.getAttribute("data-col")] = sel.value;
			refresh();
		});
	}

	function refreshOptions() {
		columns.forEach(function (c) {
			if (!c.filterable) return;
			var sel = filterRow.querySelector('select[data-col="' + c.key + '"]');
			if (!sel) return;

			// Reachable given every filter EXCEPT this column's own.
			var reachable = {};
			rows.forEach(function (r) {
				if (r[c.key] && matches(r, c.key)) reachable[r[c.key]] = 1;
			});
			var values = Object.keys(reachable).sort();
			var current = chosen[c.key] || "";
			if (current && values.indexOf(current) === -1) values.push(current);

			sel.innerHTML =
				'<option value="">All</option>' +
				values
					.map(function (v) {
						return (
							'<option value="' + esc(v) + '"' +
							(v === current ? " selected" : "") + ">" + esc(v) + "</option>"
						);
					})
					.join("");
			sel.value = current;
			sel.classList.toggle("is-active", !!current);
		});
	}

	function cell(c, row) {
		// Deadline columns carry a state the SERVER worked out -- '', 'ok',
		// 'warn', 'late' or 'done'. The thresholds are not repeated here; see
		// fps_erpnext/api/customs.py. 'done' means the status column next to it
		// says Completed (or Not Applicable), so there is nothing left to chase.
		if (row[c.key + "_state"] !== undefined) {
			var state = row[c.key + "_state"] || "none";
			return (
				'<td class="fps-ct-due fps-ct-due-' + state + '">' +
				esc(row[c.key] || "—") + "</td>"
			);
		}
		if (c.key === "status") {
			var pill = STATUS[row.status] || ["#f1f5f9", "#475569"];
			return (
				'<td><span class="fps-ct-pill" style="--fps-ct-bg: ' + pill[0] +
				"; --fps-ct-fg: " + pill[1] + '">' + esc(row.status || "—") + "</span></td>"
			);
		}
		var cls = { customer: "fps-ct-cust", job_order: "fps-ct-jo",
		            boe: "fps-ct-boe", date: "fps-ct-date" }[c.key] || "";
		var v = row[c.key] || "—";
		return (
			'<td class="' + cls + '" title="' + esc(row[c.key] || "") + '">' +
			esc(v) + "</td>"
		);
	}

	function refresh() {
		refreshOptions();

		var shown = visible();
		var active = columns.filter(function (c) {
			return chosen[c.key];
		}).length + (term ? 1 : 0);

		if (clear) clear.hidden = !active;

		if (!shown.length) {
			body.innerHTML =
				'<tr><td class="fps-ct-msg" colspan="' + columns.length +
				'">Nothing matches these filters.</td></tr>';
		} else {
			body.innerHTML = shown
				.map(function (r) {
					return (
						'<tr data-ct="' + esc(r.name) + '">' +
						columns.map(function (c) { return cell(c, r); }).join("") +
						"</tr>"
					);
				})
				.join("");
		}

		if (meta) {
			meta.textContent =
				shown.length === rows.length
					? rows.length + " declarations"
					: shown.length + " of " + rows.length + " declarations";
		}
	}

	function reset() {
		chosen = {};
		term = "";
		if (search) search.value = "";
		refresh();
	}

	// Delegated so it survives every re-render, and routed through
	// frappe.set_route rather than an <a href> so the desk navigates in place.
	body.addEventListener("click", function (e) {
		var row = e.target.closest("tr[data-ct]");
		if (!row) return;
		frappe.set_route("Form", "Customs Tracker", row.getAttribute("data-ct"));
	});

	if (search) {
		search.addEventListener("input", function () {
			term = (search.value || "").trim().toLowerCase();
			refresh();
		});
	}
	if (clear) clear.addEventListener("click", reset);

	var headerBuilt = false;
	var loaded = false;

	function load() {
		frappe
			.call({ method: "fps_erpnext.api.pipeline.get_customs_tracker" })
			.then(function (r) {
				var data = (r && r.message) || {};
				columns = data.columns || [];
				rows = data.rows || [];
				var firstLoad = !loaded;
				loaded = true;

				if (!columns.length) {
					body.innerHTML =
						'<tr><td class="fps-ct-msg">No access to the customs tracker.</td></tr>';
					return;
				}
				if (!headerBuilt) {
					buildHeader();
					headerBuilt = true;
				}
				if (!rows.length && firstLoad) {
					body.innerHTML =
						'<tr><td class="fps-ct-msg" colspan="' + columns.length +
						'">No customs entries yet.</td></tr>';
					if (meta) meta.textContent = "";
					return;
				}
				refresh();
			})
			.catch(function () {
				// Only the first load's failure replaces the grid with an error --
				// a later poll that briefly fails should leave the last good rows
				// (and whatever the viewer has filtered to) on screen.
				if (!loaded) {
					body.innerHTML =
						'<tr><td class="fps-ct-msg">Could not load the customs tracker.</td></tr>';
				}
			});
	}

	load();
	var timer = setInterval(function () {
		if (!document.body.contains(body)) {
			clearInterval(timer);
			return;
		}
		load();
	}, REFRESH_MS);
})();

style:
/* Customs board -- a spreadsheet-style filter view over every customs entry.
   One dropdown per column, sitting in the header where the column is, so the
   control and the data it narrows are never separated. */

.fps-ct {
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 10px;
	background: var(--card-bg, #fff);
	overflow: hidden;
}

.fps-ct-head {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 12px 16px;
	flex-wrap: wrap;
}

.fps-ct-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text-color, #1f272e);
}

.fps-ct-help {
	font-size: 12px;
	color: var(--text-muted, #7c7c7c);
}

.fps-ct-search {
	margin-left: auto;
	min-width: 190px;
	font-size: 12px;
	padding: 4px 9px;
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 6px;
	background: var(--control-bg, #fff);
	color: var(--text-color, #1f272e);
}

.fps-ct-clear {
	font-size: 11.5px;
	padding: 4px 10px;
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 6px;
	background: var(--control-bg, #fff);
	color: var(--text-muted, #55606b);
	cursor: pointer;
}

.fps-ct-clear:hover {
	background: var(--bg-light-gray, #f7f9fa);
}

/* Hidden rather than removed: a control that appears and disappears makes the
   header jump about as you filter. */
.fps-ct-clear[hidden] {
	visibility: hidden;
	display: inline-block;
}

.fps-ct-meta {
	width: 100%;
	font-size: 11.5px;
	color: var(--text-muted, #7c7c7c);
	font-variant-numeric: tabular-nums;
}

.fps-ct-scroll {
	overflow-x: auto;
	max-height: 560px;
	overflow-y: auto;
	border-top: 1px solid var(--border-color, #e2e8f0);
}

.fps-ct-table {
	width: 100%;
	/* Twelve columns. Below this "Not Applicable" starts ellipsing in the four
	   status columns and the two dates wrap; the container scrolls instead. */
	min-width: 1500px;
	table-layout: fixed;
	border-collapse: collapse;
	font-size: 12.5px;
}

/* Widths in source order, matching the operations workbook with each deadline
   sitting beside the status it chases:
   Status, Client, Job No., BOE, Type, Date, MOFA, MOFA due, Doc Sub, Doc due,
   Deposit, Claim.
   Client and Type get the room because they hold the long strings. The four
   status columns never exceed "Not Applicable" and the two dates never exceed
   "dd-MM-yyyy", so they are sized to exactly that and no more. */
.fps-ct-table th:nth-child(1) { width: 7%; }
.fps-ct-table th:nth-child(2) { width: 13%; }
.fps-ct-table th:nth-child(3) { width: 9%; }
.fps-ct-table th:nth-child(4) { width: 9%; }
.fps-ct-table th:nth-child(5) { width: 11%; }
.fps-ct-table th:nth-child(6) { width: 6%; }
.fps-ct-table th:nth-child(7) { width: 7%; }
.fps-ct-table th:nth-child(8) { width: 7%; }
.fps-ct-table th:nth-child(9) { width: 8%; }
.fps-ct-table th:nth-child(10) { width: 7%; }
.fps-ct-table th:nth-child(11) { width: 8%; }
.fps-ct-table th:nth-child(12) { width: 8%; }

/* Deadline cells. The state is decided server-side in
   fps_erpnext/api/customs.py -- these only paint it.

     ok    inside the window, nothing to do yet
     warn  amber: 15 days for doc submission, 9 for MOFA
     late  red:   25 days for doc submission, 12 for MOFA
     done  the status beside it says Completed / Not Applicable
     none  no clearance date, so no clock to run */
.fps-ct-due {
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-size: 11.5px;
	text-align: center;
}

.fps-ct-due-ok {
	color: var(--text-muted, #55606b);
}

.fps-ct-due-warn {
	background: #FEF3C7;
	color: #92400E;
	font-weight: 600;
}

.fps-ct-due-late {
	background: #FEE2E2;
	color: #B91C1C;
	font-weight: 700;
}

/* Struck through rather than coloured: the date is history, not a target. */
.fps-ct-due-done {
	color: var(--text-muted, #98a3b8);
	text-decoration: line-through;
}

.fps-ct-due-none {
	color: var(--text-muted, #b9c3d6);
}

.fps-ct-table thead th {
	position: sticky;
	background: var(--card-bg, #fff);
	text-align: left;
	padding: 8px 10px;
	white-space: nowrap;
}

.fps-ct-table thead tr:first-child th {
	top: 0;
	z-index: 2;
	font-size: 10.5px;
	font-weight: 600;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-muted, #7c7c7c);
}

/* Second sticky row. 27px is the height of the row above it -- they have to be
   stacked by hand, because position: sticky offsets do not accumulate. */
.fps-ct-table thead tr.fps-ct-filterrow th {
	top: 27px;
	z-index: 1;
	padding: 0 6px 8px;
	border-bottom: 1px solid var(--border-color, #e2e8f0);
}

.fps-ct-select {
	width: 100%;
	font-size: 11.5px;
	padding: 3px 4px;
	border: 1px solid var(--border-color, #e2e8f0);
	border-radius: 5px;
	background: var(--control-bg, #fff);
	color: var(--text-color, #1f272e);
}

/* An active filter has to be obvious at a glance, or you spend ten minutes
   wondering why a row you know exists is missing. */
.fps-ct-select.is-active {
	border-color: #0B4FE0;
	box-shadow: inset 0 0 0 1px #0B4FE0;
	font-weight: 600;
}

.fps-ct-table td {
	padding: 7px 10px;
	border-bottom: 1px solid var(--border-color, #f1f5f9);
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.fps-ct-table tbody tr {
	cursor: pointer;
}

.fps-ct-table tbody tr:hover {
	background: var(--bg-light-gray, #f7f9fa);
}

.fps-ct-pill {
	display: inline-block;
	padding: 2px 8px;
	border-radius: 20px;
	font-size: 11px;
	font-weight: 600;
	white-space: nowrap;
	background: var(--fps-ct-bg, #f1f5f9);
	color: var(--fps-ct-fg, #475569);
}

.fps-ct-cust {
	font-weight: 500;
	color: var(--text-color, #1f272e);
}

.fps-ct-jo,
.fps-ct-boe,
.fps-ct-date {
	font-family: var(--font-stack-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
	font-size: 11.5px;
	color: var(--text-muted, #55606b);
}

.fps-ct-msg {
	padding: 18px 16px;
	font-size: 12.5px;
	color: var(--text-muted, #7c7c7c);
	white-space: normal;
}
